async function control(action){const r=await fetch(input.provider+'/__'+action,{method:action==='status'?'GET':'POST',signal:AbortSignal.any([stop.signal,AbortSignal.timeout(2000)])});assert.equal(r.status,200);return r.json();}
function observed(){const row=JSON.parse(fs.readFileSync(path.join(root,'capacity-backend.json')));assert(row.valid&&row.installed&&row.coordinator.valid&&Date.now()-row.sampledAt<1500,'Capacity observations unavailable');assert(row.rssPeak<=1610612736);assert(row.pools.managedReserved<=78);assert(row.pools.total<=row.pools.managedReserved);assert(row.coordinator.peak.runs<=1024&&row.coordinator.peak.ownerRuns<=16&&row.coordinator.peak.lifecycle<=256&&row.coordinator.peak.ownerLifecycle<=4);for(const a of row.leaseAdmissions)assert.equal(a.valid,true,'Lease owner observations unavailable');for(const s of row.schedulers){assert(s.active<=2&&s.queued<=256&&s.ownerQueueLimit===16);}return row;}
async function until(predicate,ms=7000){const end=performance.now()+ms;while(performance.now()<end){stop.signal.throwIfAborted();if(await predicate())return;await delay(20);}throw Error('Capacity observation deadline');}
const family=u=>u.index<100?'sql':'nosql';
const runIds=new Map(),sha=value=>createHash('sha256').update(value).digest('hex'),hash=value=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
function assertPresentationDto(body,user){const expectedFamily=family(user)==='sql'?'ARIA':'NOVA',expectedTool=family(user)==='sql'?'view_cart':'view_reading_list',p=body.presentation;assert.equal(body.run.responseComposition,'workshop-result-presentation-v1');assert.equal(p?.version,'workshop-result-presentation-v1');assert.equal(p.family,expectedFamily);assert.equal(p.runId,body.run.runId);assert.equal(typeof body.response,'string');assert.equal(p.responseSha256,sha(body.response));assert.match(body.response,/Controlled capacity response; no objective success claim\./);assert(body.response.includes(`Tool result — ${expectedTool} (server-rendered):`));assert.equal(typeof p.narrative?.text,'string');assert(['model','fixture','unavailable'].includes(p.narrative.source));assert(p.narrative.errorCode===null||['MODEL_OUTPUT_LIMIT','MODEL_RESPONSE_UNAVAILABLE','MODEL_RESPONSE_ERROR'].includes(p.narrative.errorCode));assert.equal(p.narrative.sha256,sha(p.narrative.text));assert.equal(p.blocks?.length,1);const block=p.blocks[0];assert.equal(block.index,0);assert.equal(block.tool,expectedTool);assert.equal(typeof block.effectKey,'string');assert(block.effectKey.length>0);assert(hash(block.resultSha256)&&hash(block.displaySha256));report.presentationProjection.dto++;return p;}
function assertOwnerPresentationDetail(detail,body,presentation,user){assert.equal(detail.run?.runId,body.run.runId);assert.equal(detail.run.family,presentation.family);assert.deepEqual(detail.judgments,[]);const events=detail.events.filter(event=>event.node==='presentation'&&event.type==='node_end'&&event.data?.presentationSnapshot);assert.equal(events.length,1);const snapshot=events[0].data.presentationSnapshot;assert.equal(snapshot.version,presentation.version);assert.equal(snapshot.narrativeSource,presentation.narrative.source);assert.equal(snapshot.errorCode,presentation.narrative.errorCode);assert.equal(snapshot.narrativeSha256,presentation.narrative.sha256);assert.equal(snapshot.responseSha256,presentation.responseSha256);assert.deepEqual(snapshot.blocks,presentation.blocks);assert.equal(detail.run.family,family(user)==='sql'?'ARIA':'NOVA');report.presentationProjection.ownerDetails++;}
async function chat(user,options={}){const marker=`capacity-owner-${user.id}-run-${randomUUID()}`;const r=await request(user,`/api/workshop/${family(user)}/chat`,{userMessage:`Please ${family(user)==='sql'?'view my cart':'view my reading list'}. ${marker}`},{timeoutMs:60000,...options});return r;}
function assertGradingReceipt({body,detail,row,evidence,userId,term}){assert.equal(body.run?.decisionSource,'model');assert.equal(body.toolUsed,'search_products');assert.deepEqual(body.completedObjectives,[]);assert.equal(body.judgments?.length,1);const judgment=body.judgments[0];assert.equal(judgment.objectiveId,'sqli_1');assert.equal(judgment.verdict,'unavailable');assert.equal(judgment.errorCode,'INVALID_JUDGE_OUTPUT');assert.equal(detail.judgments?.length,1);assert.equal(detail.judgments[0].runId,body.run.runId);assert.equal(detail.judgments[0].objectiveId,'sqli_1');assert.equal(detail.judgments[0].verdict,'unavailable');assert.equal(detail.judgments[0].disposition,'not_pass');assert.equal(detail.judgments[0].errorCode,'INVALID_JUDGE_OUTPUT');assert.deepEqual(row,{run_id:body.run.runId,verdict:'unavailable',disposition:'not_pass',error_code:'INVALID_JUDGE_OUTPUT',owner_key:JSON.stringify(['ARIA',String(userId)]),owner_generation:'0'});assert.deepEqual(evidence,{run_id:body.run.runId,tool:'search_products',decision_source:'model',params:{searchTerm:term,maxPrice:null}});}
async function gradingProbe({user,db,request}){const marker=`capacity-owner-${user.id}-run-${randomUUID()}`,term=`' || CAST('${marker}-capacity-grading-projection-v1' AS integer) || '`,message=`Please search products using this exact searchTerm: ${term}`;good(await request(user,'/api/workshop/sql/mode',{mode:'vuln'}));const body=good(await request(user,'/api/workshop/sql/chat',{userMessage:message},{timeoutMs:60000}));const detail=good(await request(user,`/api/agent-runs/${body.run.runId}`));const rows=(await db.query(`SELECT j.run_id,j.verdict,j.disposition,j.result_json->>'errorCode' error_code,p.owner_key::text owner_key,p.owner_generation::text owner_generation FROM workshop_platform.objective_judgments j JOIN workshop_platform.grade_packets p USING(user_id,evaluation_id) WHERE j.run_id=$1 AND j.objective_id='sqli_1'`,[body.run.runId])).rows;assert.equal(rows.length,1);const evidence=(await db.query(`SELECT run_id,evidence_json->>'tool' tool,evidence_json->'invocation'->>'decisionSource' decision_source,evidence_json->'invocation'->'params' params FROM workshop_platform.objective_evidence WHERE run_id=$1 AND workshop_key='sql_injection_workshop' AND scenario='product_search'`,[body.run.runId])).rows;assert.equal(evidence.length,1);assertGradingReceipt({body,detail,row:rows[0],evidence:evidence[0],userId:user.id,term});return body.run.runId;}
function good(r){assert.equal(r.status,200,'Normal workload requires HTTP200 (429 is failure)');return r.body;}
async function login(user){const r=await request(user,'/api/auth/login',{username:user.username,password:input.password},{timeoutMs:30000,session:null});good(r);assert(r.body.token&&r.cookies.some(x=>x.startsWith('connect.sid=')));const value={token:r.body.token,cookie:r.cookies.map(x=>x.split(';')[0]).join('; ')};sessions.set(user.id,value);return value;}
