async function reads(duration=0){const start=performance.now();await Promise.all(input.users.map(async u=>{await delay((u.index*37)%499);let cycle=0;do{const at=performance.now();for(const endpoint of ['/api/workshop/config/snapshot','/api/workshop/student/stats',cycle%2?'/api/agent-runs':`/api/workshop/${family(u)}/history/${u.id}`]){const body=good(await request(u,endpoint));if(endpoint.includes('/history/')&&duration){assert(body.history.some(x=>x.message==='owned-record-'+u.id));assert(body.history.filter(x=>x.message.startsWith('owned-record-')).every(x=>x.message==='owned-record-'+u.id));}}cycle++;if(duration&&performance.now()-start<duration)await delay(Math.max(0,5000-(performance.now()-at)));}while(duration&&performance.now()-start<duration&&cycle<12);}));}
async function named(name,work){phase=name;save();const start=client.snapshot().requests.length;await work();const samples=client.snapshot().requests.slice(start);if(samples.length){const latency=summarize(samples);if(name==='arrival')assert(latency.max<=30000);if(name==='read-mix')assert(latency.p95<=2000&&latency.max<=10000);if(name==='normal-runs')assert(latency.p95<=30000&&latency.max<=60000);report.phases.push({name,...latency,statuses:samples.reduce((a,x)=>(a[x.status??x.outcome]=(a[x.status??x.outcome]||0)+1,a),{})});}else report.phases.push({name,observed:true});report.observations.push(observed());save();}
