 const transactionObserver=createTransactionObserver(pairs);let pgSamples=0,sampling=false,sampleError=false,pgTimer,samplePending,draining=false;
 function samplePg(){if(sampling)return samplePending;sampling=true;samplePending=(async()=>{try{if(++pgSamples>1000)throw Object.assign(Error('Physical sample limit'),{code:'SAMPLE_LIMIT'});const raw=(await observerDb.query(ACTIVITY_SQL)).rows;assert.equal(raw.length,1);const value=transactionObserver.inspect(raw[0]);report.pgObservation=value;return value;}catch(error){sampleError=true;report.pgSampleFailures??={count:0,reasons:{},first:[]};report.pgSampleFailures.count++;const detail=physicalSampleFailure(error,undefined,pgSamples,phase,performance.now());detail.metadata=metadataDiagnostic(error);if(error.code==='PG_IDLE_AGE_LIMIT')detail.observation=error.observation;report.pgSampleFailures.reasons[detail.code||detail.reason]=(report.pgSampleFailures.reasons[detail.code||detail.reason]||0)+1;if(report.pgSampleFailures.first.length<8)report.pgSampleFailures.first.push(detail);throw error;}finally{sampling=false;}})();return samplePending;}
